class MobileMenu{constructor(){this.menuContainerAll=document.querySelectorAll(".js-menu-container");this.menu=document.querySelector(".js-menu");this.buttons=document.querySelectorAll(".js-open-menu");this.body=document.querySelector("body");this.bodyOverflowClass="no-overflow";this._bindEvents()}_bindEvents(){this.buttons.forEach(button=>{button.addEventListener("click",()=>{this.menuContainerAll.forEach(menuContainer=>{menuContainer.classList.toggle("active")});this.buttons.forEach(button=>{button.classList.toggle("active")});this.body.classList.toggle(this.bodyOverflowClass)})})}remove(){this.menuContainerAll.forEach(menuContainer=>{menuContainer.classList.remove("active")});this.buttons.forEach(button=>{button.classList.remove("active")});this.body.classList.remove(this.bodyOverflowClass)}}